use vstd::prelude::*;
use vstd::seq::*;
use vstd::pervasive::*;

verus! {

spec fn count_eligible(participations: Seq<int>, k: int) -> int
    recommends k >= 0 && k <= 5
{
    // Count how many elements in participations satisfy: 5 - attendance ≥ k
    participations.filter(|i| 5 - i >= k).len()
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> (result: u8)
    requires
        k <= 5,
        forall |i: int| 0 <= i && i < participations.len() ==> 
            participations.index(i) as int <= 5,
        n >= 0,
    ensures
        result == (count_eligible(
            participations.subrange(0, if n as int <= participations.len() { n as int } else { participations.len() } as int).map(|x| x as int),
            k as int
        ) / 3) as u8,
{
    // Determine how many elements to consider
    let limit = if (n as usize) < participations.len() {
        n as usize
    } else {
        participations.len()
    };
    
    // Count eligible participants
    let mut eligible_count: u8 = 0;
    let mut i: usize = 0;
    
    while i < limit
        invariant
            i <= limit,
            eligible_count as int == count_eligible(
                participations.subrange(0, i as int).map(|x| x as int),
                k as int
            ),
    {
        let attendance = participations[i];
        if 5 - attendance >= k {
            eligible_count += 1;
        }
        i += 1;
    }
    
    // Return the maximum number of teams (integer division by 3)
    eligible_count / 3
}

} // verus!